using System.Net.Http;using System.Text.RegularExpressions;using System.Text;
class Program{static async Task Main(string[] a){var re=new Regex(@"(?i)[a-z0-9._%+-]+\s*(?:@|\[at\]|\(at\))\s*[a-z0-9.-]+\s*(?:\.|\[dot\]|\(dot\))\s*[a-z]{2,}");var set=new HashSet<string>();using var c=new HttpClient();foreach(var u in a.Where(x=>x.StartsWith("http"))){try{var t=await c.GetStringAsync(u);foreach(Match m in re.Matches(t)){var e=Regex.Replace(m.Value,"\\s+","").ToLower().Replace("[at]","@").Replace("(at)","@").Replace("[dot]",".").Replace("(dot)",".");set.Add(e);}Console.WriteLine($"{{\"event\":\"page\",\"url\":\"{u}\",\"emails\":{set.Count}}}");}catch(Exception ex){Console.Error.WriteLine(ex.Message);}}await File.WriteAllLinesAsync("emails.txt",set);await File.WriteAllLinesAsync("emails.csv",new[]{"email"}.Concat(set));}}
